class Pizza {
    String size, crust, topping;
    Pizza(String size) {
        this(size, "Thin");
        System.out.println("1-arg done");
    }
    Pizza(String size, String crust) {
        this(size, crust, "Cheese");
        System.out.println("2-arg done");
    }
    Pizza(String size, String crust, String topping) {
        this.size    = size;
        this.crust   = crust;
        this.topping = topping;
        System.out.println("3-arg done: " + size + ", " + crust + ", " + topping);
    }
}
new Pizza("Large");

