public class Logger {
    private static Logger instance;
    private final String logFileName;

    private Logger() {
        this.logFileName = "app_" + System.currentTimeMillis() + ".log";
        System.out.println("Logger initialized: " + logFileName);
    }

    public static Logger getInstance() {
        if (instance == null) {
            instance = new Logger();
        }
        return instance;
    }

    public void log(String message) {
        System.out.println("[LOG → " + logFileName + "] " + message);
    }
}
// Usage:
Logger l1 = Logger.getInstance();
Logger l2 = Logger.getInstance();
System.out.println(l1 == l2); // true — same object
l1.log("Application started");
l2.log("User logged in"); // Same logger instance

