public final class ImmutablePoint {
    private final double x;
    private final double y;

    // Private constructor — direct Cartesian
    private ImmutablePoint(double x, double y) {
        this.x = x;
        this.y = y;
    }

    // Static factory — Cartesian
    public static ImmutablePoint fromCartesian(double x, double y) {
        return new ImmutablePoint(x, y);
    }

    // Static factory — Polar
    public static ImmutablePoint fromPolar(double radius, double angleRadians) {
        return new ImmutablePoint(
            radius * Math.cos(angleRadians),
            radius * Math.sin(angleRadians)
        );
    }

    public double getX() { return x; }
    public double getY() { return y; }

    public double distanceTo(ImmutablePoint other) {
        return Math.sqrt(Math.pow(x - other.x, 2) + Math.pow(y - other.y, 2));
    }

    @Override
    public String toString() {
        return String.format("(%.2f, %.2f)", x, y);
    }
}
// Usage:
ImmutablePoint p1 = ImmutablePoint.fromCartesian(3, 4);
ImmutablePoint p2 = ImmutablePoint.fromPolar(5, Math.PI / 4);
System.out.println(p1); // (3.00, 4.00)
System.out.println(p2); // (3.54, 3.54)
System.out.println(p1.distanceTo(p2)); // ~0.65
